INSERT INTO plot_points (universe_slug, id, work_slug, character_id, arc_id, at, text) VALUES
  ('fate', 'pp-stay-night-1', 'fate-stay-night-2006', 'shirou-emiya-fsn', 'stay-night-fate-route', 1, 'Shirou Emiya wird ungewollt in den fünften Heiligen Gralkrieg gezogen und beschwört Saber.'),
  ('fate', 'pp-zero-1', 'fate-zero', 'kiritsugu-emiya', 'zero-fourth-war', 1, 'Kiritsugu Emiya kämpft als Meister von Saber im vierten Heiligen Gralkrieg um den Gral.'),
  ('fate', 'pp-proto-1', 'fate-prototype', 'arthur-pendragon-proto', 'proto-tokyo-1991', 1, 'Arthur Pendragon kämpft im Tokio-Gralkrieg von 1991 an der Seite von Manaka Sajyou.'),
  ('fate', 'pp-prisma-illya-1', 'fate-kaleid-liner-prisma-illya', 'illya-kaleid', 'prisma-illya-transformation', 1, 'Illyasviel wird von Magical Ruby zur Kaleidscope-Magical-Girl gemacht und muss Klassenkarten sammeln.'),
  ('fate', 'pp-ubw-1', 'fate-stay-night-unlimited-blade-works', 'rin-tohsaka', 'ubw-route', 1, 'Rin Tohsaka führt Shirou durch ihre Route des Gralkriegs und stellt ihn Archer gegenüber.'),
  ('fate', 'pp-apocrypha-1', 'fate-apocrypha', 'sieg-apocrypha', 'apocrypha-great-war', 1, 'Der Homunculus Sieg entkommt als Ersatz-Servant der Roten Fraktion und sucht seinen eigenen Weg.'),
  ('fate', 'pp-oath-1', 'fate-kaleid-liner-prisma-illya-oath-under-snow', 'miyu-edelfelt-oath', 'prisma-oath-shirou', 45, 'Shirou Emiya gewinnt den Ainsworth-Gralkrieg in einer einzigen Nacht, um Miyu in eine andere Welt zu retten.'),
  ('fate', 'pp-hf1-1', 'fate-heavens-feel-1-presage-flower', 'sakura-matou-hf', 'hf-1-shadow', 10, 'Sakura Matous dunkles Geheimnis beginnt Shirous Welt zu erschüttern.'),
  ('fate', 'pp-lostroom-1', 'fate-grand-order-moonlight-lostroom', 'ritsuka-fujimaru', 'fgo-lostbelt-prologue', 5, 'Ritsuka Fujimaru und Mash Kyrielight entdecken zu Weihnachten Chaldeas verborgenen ''Lost Room''.'),
  ('fate', 'pp-gohan-1', 'todays-menu-for-the-emiya-family', 'shirou-emiya-gohan', 'gohan-alltag', 1, 'Shirou kocht ein saisonales Gericht und bringt Rin, Sakura und Taiga an einen gemeinsamen Tisch.'),
  ('fate', 'pp-hf2-1', 'fate-heavens-feel-2-lost-butterfly', 'shirou-emiya-hf', 'hf-2-corruption', 60, 'Shirou nimmt Angra Mainyus Makel in sich auf, um Sakura zu retten.'),
  ('fate', 'pp-babylonia-1', 'fate-grand-order-babylonia', 'mash-kyrielight', 'babylonia-singularity', 3, 'Mash Kyrielight begleitet den Meister ins alte Uruk, die erste verlorene Singularität.'),
  ('fate', 'pp-hf3-1', 'fate-heavens-feel-3-spring-song', 'illyasviel-hf', 'hf-3-finale', 90, 'Illyasviel von Einzbern opfert sich im finalen Kampf um Sakuras Erlösung.'),
  ('fate', 'pp-camelot-1', 'fate-grand-order-camelot', 'lancelot-camelot', 'camelot-round-table', 30, 'Lancelot verteidigt als Wahnsinniger Ritter die Tafelrunde gegen Chaldeas Meister.');
