INSERT INTO plot_points (universe_slug, id, work_slug, character_id, arc_id, at, text) VALUES
  ('wizarding-world', 'pp-fb1-1', 'fantastic-beasts-1', 'newt-fb1', 'fb1-koffer', 5, 'Schmuggelt seinen magischen Koffer voller Fantastischer Tierwesen mit nach New York.'),
  ('wizarding-world', 'pp-fb1-2', 'fantastic-beasts-1', 'newt-fb1', 'fb1-koffer', 80, 'Jagt gemeinsam mit Jacob die entkommenen Tierwesen quer durch New York.'),
  ('wizarding-world', 'pp-fb1-3', 'fantastic-beasts-1', 'tina-fb1', 'fb1-koffer', 20, 'Verhaftet Newt wegen des Verdachts illegaler Zauberei.'),
  ('wizarding-world', 'pp-fb1-4', 'fantastic-beasts-1', 'jacob-fb1', 'fb1-koffer', 15, 'Vertauscht als No-Maj versehentlich seinen Koffer mit Newts magischem Exemplar.'),
  ('wizarding-world', 'pp-fb1-5', 'fantastic-beasts-1', 'credence-fb1', 'fb1-schatten', 60, 'Wird von Graves als Werkzeug gegen die eigene Ziehmutter benutzt.'),
  ('wizarding-world', 'pp-fb1-6', 'fantastic-beasts-1', 'credence-fb1', 'fb1-schatten', 120, 'Entpuppt sich als Ursprung des zerstörerischen Obscurus.'),
  ('wizarding-world', 'pp-fb2-1', 'fantastic-beasts-2', 'newt-fb2', 'fb2-herkunft', 10, 'Wird von Dumbledore gebeten, Credence in Paris aufzuspüren, bevor Grindelwald ihn findet.'),
  ('wizarding-world', 'pp-fb2-2', 'fantastic-beasts-2', 'grindelwald-fb2', 'fb2-aufstieg', 5, 'Entkommt seiner Gefangenschaft und beginnt, Anhänger für seine reinblütige Vision zu sammeln.'),
  ('wizarding-world', 'pp-fb2-3', 'fantastic-beasts-2', 'grindelwald-fb2', 'fb2-aufstieg', 125, 'Enthüllt Credence eine Lüge über dessen wahre Herkunft, um ihn auf seine Seite zu ziehen.'),
  ('wizarding-world', 'pp-fb2-4', 'fantastic-beasts-2', 'credence-fb2', 'fb2-herkunft', 90, 'Sucht in Paris verzweifelt nach seiner echten Familie.'),
  ('wizarding-world', 'pp-fb2-5', 'fantastic-beasts-2', 'dumbledore-fb2', 'fb2-aufstieg', 15, 'Kann Grindelwald wegen eines alten Blutpakts nicht selbst entgegentreten.'),
  ('wizarding-world', 'pp-fb3-1', 'fantastic-beasts-3', 'newt-fb3', 'fb3-wahl', 20, 'Schmiedet mit Dumbledores Verbündeten einen Plan gegen Grindelwalds Wahlkampagne.'),
  ('wizarding-world', 'pp-fb3-2', 'fantastic-beasts-3', 'dumbledore-fb3', 'fb3-pakt', 30, 'Erklärt seinen Verbündeten den Blutpakt, der ihn an Grindelwald bindet.'),
  ('wizarding-world', 'pp-fb3-3', 'fantastic-beasts-3', 'dumbledore-fb3', 'fb3-pakt', 135, 'Zerstört im entscheidenden Duell den Blutpakt endgültig.'),
  ('wizarding-world', 'pp-fb3-4', 'fantastic-beasts-3', 'grindelwald-fb3', 'fb3-wahl', 100, 'Kandidiert offen für das Amt des Supreme Mugwump des Zaubererbunds.'),
  ('wizarding-world', 'pp-fb3-5', 'fantastic-beasts-3', 'credence-fb3', 'fb3-pakt', 110, 'Wendet sich im entscheidenden Moment gegen Grindelwald.'),
  ('wizarding-world', 'pp-ps-1', 'philosophers-stone', 'harry-ps', 'ps-entdeckung', 20, 'Erfährt von Hagrid, dass er ein Zauberer ist.'),
  ('wizarding-world', 'pp-ps-2', 'philosophers-stone', 'harry-ps', 'ps-stein', 140, 'Stellt sich Quirrell und Voldemort im Kampf um den Stein der Weisen.'),
  ('wizarding-world', 'pp-ps-3', 'philosophers-stone', 'ron-ps', 'ps-entdeckung', 45, 'Freundet sich mit Harry im Hogwarts-Express an.'),
  ('wizarding-world', 'pp-ps-4', 'philosophers-stone', 'hermine-ps', 'ps-entdeckung', 60, 'Rettet Harry und Ron vor einem Bergtroll und wird ihre Freundin.'),
  ('wizarding-world', 'pp-ps-5', 'philosophers-stone', 'quirrell-ps', 'ps-stein', 145, 'Wird als Wirt Voldemorts enttarnt, der in seinem Hinterkopf lebt.'),
  ('wizarding-world', 'pp-cos-1', 'chamber-of-secrets', 'harry-cos', 'cos-kammer', 30, 'Hört eine unheimliche Stimme, die nur er wahrnehmen kann.'),
  ('wizarding-world', 'pp-cos-2', 'chamber-of-secrets', 'harry-cos', 'cos-kammer', 150, 'Tötet den Basilisken tief in der Kammer des Schreckens.'),
  ('wizarding-world', 'pp-cos-3', 'chamber-of-secrets', 'ron-cos', 'cos-freundschaft', 10, 'Fliegt mit Harry im fliegenden Ford Anglia nach Hogwarts.'),
  ('wizarding-world', 'pp-cos-4', 'chamber-of-secrets', 'hermine-cos', 'cos-kammer', 100, 'Wird durch den Basilisken-Blick versteinert.'),
  ('wizarding-world', 'pp-cos-5', 'chamber-of-secrets', 'riddle-cos', 'cos-kammer', 120, 'Enthüllt sich als Tom Riddles Erinnerung, die auf Ginnys Seele zehrt.'),
  ('wizarding-world', 'pp-poa-1', 'prisoner-of-azkaban', 'harry-poa', 'poa-sirius', 30, 'Erfährt, dass der entflohene Sirius Black hinter ihm her sein soll.'),
  ('wizarding-world', 'pp-poa-2', 'prisoner-of-azkaban', 'harry-poa', 'poa-zeitumkehrer', 130, 'Rettet mit Hermines Zeitumkehrer Sirius und Seidenschnabel vor der Hinrichtung.'),
  ('wizarding-world', 'pp-poa-3', 'prisoner-of-azkaban', 'hermine-poa', 'poa-zeitumkehrer', 30, 'Nutzt heimlich einen Zeitumkehrer, um mehrere Kurse gleichzeitig zu besuchen.'),
  ('wizarding-world', 'pp-poa-4', 'prisoner-of-azkaban', 'ron-poa', 'poa-sirius', 95, 'Wird bei der Verfolgung von Sirius'' Animagus-Ratte in die Peitschende Weide gezogen.'),
  ('wizarding-world', 'pp-poa-5', 'prisoner-of-azkaban', 'sirius-poa', 'poa-sirius', 100, 'Enthüllt, dass nicht er, sondern Peter Pettigrew die Potters verraten hat.'),
  ('wizarding-world', 'pp-gof-1', 'goblet-of-fire', 'harry-gof', 'gof-turnier', 40, 'Wird trotz Mindestalter unfreiwillig als vierter Champion ausgewählt.'),
  ('wizarding-world', 'pp-gof-2', 'goblet-of-fire', 'harry-gof', 'gof-voldemort', 150, 'Entkommt nur knapp Voldemorts Wiedergeburt auf dem Friedhof.'),
  ('wizarding-world', 'pp-gof-3', 'goblet-of-fire', 'ron-gof', 'gof-turnier', 60, 'Zerstreitet sich mit Harry aus Eifersucht über dessen Teilnahme.'),
  ('wizarding-world', 'pp-gof-4', 'goblet-of-fire', 'hermine-gof', 'gof-turnier', 110, 'Geht mit Viktor Krum zum Weihnachtsball.'),
  ('wizarding-world', 'pp-gof-5', 'goblet-of-fire', 'voldemort-gof', 'gof-voldemort', 145, 'Erlangt durch ein dunkles Ritual einen neuen, vollständigen Körper zurück.'),
  ('wizarding-world', 'pp-ootp-1', 'order-of-the-phoenix', 'harry-ootp', 'ootp-widerstand', 70, 'Gründet heimlich Dumbledores Armee, um echte Verteidigung zu lehren.'),
  ('wizarding-world', 'pp-ootp-2', 'order-of-the-phoenix', 'harry-ootp', 'ootp-prophezeiung', 130, 'Erfährt im Zaubereiministerium den vollen Wortlaut der Prophezeiung.'),
  ('wizarding-world', 'pp-ootp-3', 'order-of-the-phoenix', 'hermine-ootp', 'ootp-widerstand', 65, 'Schlägt die Gründung von Dumbledores Armee vor.'),
  ('wizarding-world', 'pp-ootp-4', 'order-of-the-phoenix', 'umbridge-ootp', 'ootp-widerstand', 20, 'Übernimmt als neue Lehrerin die zunehmende Kontrolle über Hogwarts.'),
  ('wizarding-world', 'pp-ootp-5', 'order-of-the-phoenix', 'sirius-ootp', 'ootp-prophezeiung', 132, 'Stirbt im Duell mit Bellatrix Lestrange im Ministerium.'),
  ('wizarding-world', 'pp-hbp-1', 'half-blood-prince', 'harry-hbp', 'hbp-erinnerungen', 50, 'Sammelt mit Dumbledore Erinnerungen über Voldemorts Jugend.'),
  ('wizarding-world', 'pp-hbp-2', 'half-blood-prince', 'harry-hbp', 'hbp-snape', 145, 'Muss mit ansehen, wie Snape Dumbledore tötet.'),
  ('wizarding-world', 'pp-hbp-3', 'half-blood-prince', 'draco-hbp', 'hbp-snape', 100, 'Erhält von Voldemort den Auftrag, Dumbledore zu töten.'),
  ('wizarding-world', 'pp-hbp-4', 'half-blood-prince', 'snape-hbp', 'hbp-snape', 148, 'Erfüllt den Unbrechbaren Schwur und tötet Dumbledore auf dem Astronomieturm.'),
  ('wizarding-world', 'pp-hbp-5', 'half-blood-prince', 'dumbledore-hbp', 'hbp-erinnerungen', 60, 'Zeigt Harry, wie Voldemort erstmals einen Horkrux erschuf.'),
  ('wizarding-world', 'pp-dh1-1', 'deathly-hallows-1', 'harry-dh1', 'dh1-flucht', 10, 'Flieht mit sieben Doppelgängern vor den Todessern aus Privet Drive.'),
  ('wizarding-world', 'pp-dh1-2', 'deathly-hallows-1', 'harry-dh1', 'dh1-horkruxe', 120, 'Zerstört gemeinsam mit Ron Slytherins Medaillon-Horkrux.'),
  ('wizarding-world', 'pp-dh1-3', 'deathly-hallows-1', 'ron-dh1', 'dh1-horkruxe', 90, 'Verlässt aus Eifersucht und Erschöpfung vorübergehend seine Freunde.'),
  ('wizarding-world', 'pp-dh1-4', 'deathly-hallows-1', 'hermine-dh1', 'dh1-flucht', 5, 'Löscht das Gedächtnis ihrer Eltern, um sie vor Voldemort zu schützen.'),
  ('wizarding-world', 'pp-dh1-5', 'deathly-hallows-1', 'dobby-dh1', 'dh1-flucht', 140, 'Rettet die Gruppe aus Malfoy Manor und stirbt dabei.'),
  ('wizarding-world', 'pp-dh2-1', 'deathly-hallows-2', 'harry-dh2', 'dh2-hogwarts', 40, 'Bricht in die Verliese von Gringotts ein, um einen weiteren Horkrux zu holen.'),
